<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$resultPath=!empty($_FILES['result_file'])?save_upload($_FILES['result_file'],'results'):null;$q=$p->prepare("UPDATE orders SET status=?,result_note=? WHERE id=?");$q->execute([$status,trim($_POST['result_note']??''),$id]);$q=$p->prepare("SELECT o.*,u.telegram_id FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?");$q->execute([$id]);$o=$q->fetch();if($resultPath){$p->prepare("INSERT INTO order_fields(order_id,field_label,field_key,field_type,value_text,file_path)VALUES(?,?,?,?,?,?)")->execute([$id,'فایل نتیجه','result_file','file','',$resultPath]);$full=__DIR__.'/../../storage/'.$resultPath;$caption='📎 فایل نتیجه سفارش '.$o['order_no'];if(is_file($full))telegram('sendDocument',['chat_id'=>$o['telegram_id'],'document'=>new CURLFile($full),'caption'=>$caption]);}if($status==='completed')send_msg($o['telegram_id'],'✅ سفارش <code>'.$o['order_no'].'</code> تکمیل شد.'."\n\n".e($o['result_note']??''));}$rows=$p->query("SELECT o.*,u.telegram_id,s.name service_name FROM orders o JOIN users u ON u.id=o.user_id JOIN services s ON s.id=o.service_id ORDER BY o.id DESC LIMIT 100")->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>سفارش‌ها</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1200px;margin:30px auto}.card{background:#fff;padding:20px;border-radius:18px}select,textarea{padding:8px;width:100%;box-sizing:border-box;margin:5px 0}button{background:#1687d9;color:#fff;border:0;padding:8px 12px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #eee;text-align:right}</style><div class=wrap><a href=/admin/index.php>← داشبورد</a><div class=card><h2>📦 سفارش‌ها</h2><table><tr><th>شماره</th><th>خدمت</th><th>مبلغ</th><th>کاربر</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><code><?=e($r['order_no'])?></code></td><td><?=e($r['service_name'])?></td><td><?=money((int)$r['amount'])?></td><td><?=e($r['telegram_id'])?></td><td><?=e($r['status'])?></td><td><form method=post enctype="multipart/form-data"><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=id value=<?=$r['id']?>><select name=status><option value=pending>pending</option><option value=processing>processing</option><option value=completed>completed</option><option value=cancelled>cancelled</option></select><textarea name=result_note placeholder="توضیح نتیجه"></textarea><input type=file name=result_file accept=".jpg,.jpeg,.png,.pdf,.doc,.docx"><button>ذخیره</button></form></td></tr><?php endforeach;?></table></div></div>
